def rc(s): return s.translate(str.maketrans('ACGT','TGCA'))[::-1]
comp=str.maketrans('ACGT','TGCA')
def orfs(s,minlen=200):
    res=[]
    for strand,t in [('+',s),('-',rc(s))]:
        for f in range(3):
            # find stop-free regions
            i=f
            start=None
            for j in range(f,len(t)-2,3):
                cod=t[j:j+3]
                if cod in ('ATG','GTG','TTG') and start is None:
                    start=j
                if cod in ('TAA','TAG','TGA'):
                    if start is not None:
                        if j-start>=minlen:
